-- Scontro a squadre (SPEC §5.19, docs/COMBAT.md), stage 5, batch 11: the kits of 25 more characters
-- that do not come out of the packs, P253 to P277 (10 Delta, 6 Gamma, 4 Beta, 3 Alfa, 2 Omega)
-- (src/lib/combat-kits-batch-11.ts on 25 November 2026, described in docs/COMBAT-KITS.md). Each one
-- was simulated on its own card: with its kit, in a random team against a random team, it wins
-- between 46% and 56%.
--
-- A kit an admin already saved from the EDITOR for one of these characters stays as it is.

insert into public.combat_kits (definition_id, kit)
select d.id, k.kit::jsonb
