join public.card_definitions d on d.code = k.code
on conflict (definition_id) do nothing;

do $$
begin
  if (select count(*) from public.card_definitions d join public.combat_kits k on k.definition_id = d.id
      where d.code in ('P253', 'P254', 'P255', 'P256', 'P257', 'P258', 'P259', 'P260', 'P261', 'P262', 'P263', 'P264', 'P265', 'P266', 'P267', 'P268', 'P269', 'P270', 'P271', 'P272', 'P273', 'P274', 'P275', 'P276', 'P277')) <> 25 then
    raise exception 'a character of the eleventh batch has no kit';
  end if;
end $$;
